void test_PERF_002_01(void)
{
    motor_sequence_t sequence;
    unsigned int i;

    motor_sequence_init(&sequence);

    for (i = 0U; i < 299U; ++i) {
        motor_sequence_step(&sequence, APP_MOTOR_CONTROL_PERIOD_MS);
    }

    TEST_ASSERT_EQUAL_INT(2990, (int)sequence.elapsed_ms);
    TEST_ASSERT_EQUAL_INT(MOTOR_SEQUENCE_BOOT_DELAY, sequence.state);

    motor_sequence_step(&sequence, APP_MOTOR_CONTROL_PERIOD_MS);

    TEST_ASSERT_EQUAL_INT(3000, (int)sequence.elapsed_ms);
    TEST_ASSERT_EQUAL_INT(MOTOR_SEQUENCE_STARTUP_RAMP, sequence.state);
}
